import {
  action,
  computed,
  makeAutoObservable,
  observable,
  runInAction,
} from "mobx";
import { BtjConnection } from "../services/btj-connection";
import { Btj } from "../services/btj-messages";
import type { BtjTransport } from "../services/btj-transport";
import { createDemoTransport } from "../services/virtual-transport";
import { scanAndSelectBluetoothTransport } from "../services/web-bluetooth-transport";
import { scanAndSelectWebUsbTransport } from "../services/webusb-transport";
import { XEP80_STATE_SIZE, decodeXep80Update } from "../xep80/decoder";

export interface DeviceEntry {
  addr: Btj.DevAddr;
  config: Btj.DevConfig;
  state: Btj.DevState;
}

export interface ProfileEntry {
  pins: Map<number, Btj.PinConfig>;
  pots: Map<number, Btj.PotConfig>;
  intgs: Map<number, Btj.IntgConfig>;
}

export interface ErrorEntry {
  id: number;
  message: string;
  source?: string; // e.g., 'connection', 'device', 'profile'
}

export type ConnectionTransport = "bluetooth" | "usb" | "demo";

type Xep80ViewElement = HTMLElement & {
  renderFrame(state: Uint8Array, synced?: boolean): void;
};

export class BtjModel {
  private _errorIdCounter = 0;

  constructor() {
    // Make the instance observable so MobX tracks fields and methods
    // (works regardless of decorator transform settings).
    makeAutoObservable(this);
  }

  @observable
  conn: BtjConnection | null = null;

  @observable
  errors: ErrorEntry[] = [];

  @observable
  lastTransport: ConnectionTransport | null = null;

  @observable
  sysInfo: Btj.SysInfo | null = null;

  @observable
  sysState: Btj.SysState | null = null;

  @observable
  joyPort: Btj.JoyPortState | null = null;

  @observable
  devices: DeviceEntry[] = [];

  @observable
  advDevices: Btj.AdvData[] = [];

  @observable
  profiles: Map<number, ProfileEntry> = new Map();

  @observable
  xep80State: Uint8Array = new Uint8Array(XEP80_STATE_SIZE);

  @observable
  xep80Synced = false;

  @computed
  get connected(): boolean {
    return this.conn != null;
  }

  private formatError(err: unknown): string {
    if (err instanceof Btj.Error) {
      return `Device error: ${err.code}`;
    }
    if (err instanceof Error) {
      return err.message;
    }
    return String(err);
  }

  @action
  logError(err: unknown, source?: string): void {
    console.error("Blue2Joy error", { source, error: err });
    const error: ErrorEntry = {
      id: ++this._errorIdCounter,
      message: this.formatError(err),
      source,
    };
    this.errors.push(error);
  }

  @action
  clearErrors(): void {
    this.errors = [];
  }

  @action
  removeError(id: number): void {
    this.errors = this.errors.filter((e) => e.id !== id);
  }

  @action
  async scanAndConnect(): Promise<void> {
    try {
      const transport = await scanAndSelectBluetoothTransport();
      this.lastTransport = "bluetooth";
      await this.connect(transport);
    } catch (err: unknown) {
      if (err instanceof Error && err.name === "NotFoundError") {
        // User canceled the chooser - not an error
        return;
      }
      this.logError(err, "connection");
    }
  }

  @action
  async scanAndConnectUsb(): Promise<void> {
    try {
      const transport = await scanAndSelectWebUsbTransport();
      this.lastTransport = "usb";
      await this.connect(transport);
    } catch (err: unknown) {
      if (err instanceof Error && err.name === "NotFoundError") {
        // User canceled the chooser - not an error
        return;
      }
      this.logError(err, "connection");
    }
  }

  @action
  async connectDemo(): Promise<void> {
    try {
      this.lastTransport = "demo";
      await this.connect(createDemoTransport());
    } catch (err: unknown) {
      this.logError(err, "connection");
    }
  }

  @action
  async reconnectLastTransport(): Promise<void> {
    switch (this.lastTransport) {
      case "bluetooth":
        await this.scanAndConnect();
        break;
      case "usb":
        await this.scanAndConnectUsb();
        break;
      case "demo":
        await this.connectDemo();
        break;
      default:
        this.logError("No previous transport available", "connection");
    }
  }

  @action
  private processSysStateUpdateEvent(payload: DataView) {
    const evt = new Btj.SysStateUpdateEvent();
    evt.parseMessage(payload);
    this.sysState = evt.data;
  }

  @action
  private processAdvListUpdateEvent(payload: DataView) {
    const evt = new Btj.AdvListUpdateEvent();
    evt.parseMessage(payload);
    if (!evt.deleted) {
      // New or updated entry
      const idx = this.advDevices.findIndex((dev) =>
        dev.addr.equals(evt.data.addr),
      );
      if (idx >= 0) {
        // replace existing entry
        this.advDevices.splice(idx, 1, evt.data);
      } else {
        // append new entry
        this.advDevices.push(evt.data);
      }
    } else {
      // Entry removed
      this.advDevices = this.advDevices.filter(
        (dev) => !dev.addr.equals(evt.data.addr),
      );
    }
  }

  @action
  private processDevListUpdateEvent(payload: DataView) {
    const evt = new Btj.DevListUpdateEvent();
    evt.parseMessage(payload);
    if (!evt.deleted) {
      // New or updated entry
      const idx = this.devices.findIndex((dev) => dev.addr.equals(evt.addr));
      const entry = { addr: evt.addr, config: evt.config!, state: evt.state! };
      if (idx >= 0) {
        // replace existing entry
        this.devices.splice(idx, 1, entry);
      } else {
        // append new entry
        this.devices.push(entry);
      }
    } else {
      // Entry removed
      this.devices = this.devices.filter((dev) => !dev.addr.equals(evt.addr));
    }
  }

  @action
  private processProfileUpdateEvent(payload: DataView) {
    const evt = new Btj.ProfileUpdateEvent();
    evt.parseMessage(payload);
    const entry: ProfileEntry = {
      pins: evt.pins,
      pots: evt.pots,
      intgs: evt.intgs,
    };
    this.profiles.set(evt.profile, entry);
  }

  @action
  private processJoyPortUpdateEvent(payload: DataView) {
    const evt = new Btj.JoyPortUpdateEvent();
    evt.parseMessage(payload);
    this.joyPort = evt.data;
    if (evt.data.mode !== Btj.JoyPortMode.UART) {
      this.resetXep80TransportState();
    }
  }

  @action
  private processXep80UpdateEvent(payload: DataView) {
    const data = new Uint8Array(
      payload.buffer,
      payload.byteOffset,
      payload.byteLength,
    );
    decodeXep80Update(data, this.xep80State);
    this.xep80Synced = true;

    // Update the XEP80 view with the new state
    const view = document.querySelector<Xep80ViewElement>("xep80-view");
    if (view?.renderFrame) {
      view.renderFrame(this.xep80State, this.xep80Synced);
    }
  }

  // Handler forwarded to BtjConnection to receive async events from the device
  private processEvent = (msgId: number, payload: DataView) => {
    try {
      switch (msgId) {
        case Btj.MsgId.EVT_SYS_STATE_UPDATE:
          this.processSysStateUpdateEvent(payload);
          break;
        case Btj.MsgId.EVT_ADV_LIST_UPDATE:
          this.processAdvListUpdateEvent(payload);
          break;
        case Btj.MsgId.EVT_DEV_LIST_UPDATE:
          this.processDevListUpdateEvent(payload);
          break;
        case Btj.MsgId.EVT_PROFILE_UPDATE:
          this.processProfileUpdateEvent(payload);
          break;
        case Btj.MsgId.EVT_JOY_PORT_UPDATE:
          this.processJoyPortUpdateEvent(payload);
          break;
        case Btj.MsgId.EVT_XEP80_UPDATE:
          this.processXep80UpdateEvent(payload);
          break;
      }
    } catch (err) {
      console.error("Failed to handle event", err);
    }
  };

  @action
  async connect(transport: BtjTransport): Promise<void> {
    this.removeAllDevices();
    this.removeAllProfiles();
    this.resetXep80TransportState();

    this.clearErrors();

    this.conn = new BtjConnection(transport, this.processEvent, (reason) => {
      this.logError(reason, "connection");
      this.disconnect();
    });
    try {
      await this.conn.connect();
      // GetApiVersion serves as a synchronization command
      this.resetXep80TransportState();
      await this.conn.invoke(new Btj.GetApiVersion());
      const sysInfo = (await this.conn.invoke(new Btj.GetSysInfo())).data;
      runInAction(() => {
        this.sysInfo = sysInfo;
      });
    } catch (err: unknown) {
      this.logError(err, "connection");
      this.disconnect();
    }
  }

  @action
  disconnect() {
    // Close underlying BLE connection if any
    if (this.conn) {
      // best-effort disconnect; do not await
      this.conn.disconnect().catch((err) => {
        console.error("Failed to disconnect Blue2Joy connection", err);
      });
    }
    this.conn = null;
    this.sysInfo = null;
    this.sysState = null;
    this.resetXep80TransportState();
  }

  @action
  private resetXep80TransportState() {
    this.xep80State = new Uint8Array(XEP80_STATE_SIZE);
    this.xep80Synced = false;

    const view = document.querySelector<Xep80ViewElement>("xep80-view");
    if (view?.renderFrame) {
      view.renderFrame(this.xep80State, this.xep80Synced);
    }
  }

  getProfile(id: number): ProfileEntry | undefined {
    return this.profiles.get(id);
  }

  @action
  removeAllProfiles() {
    this.profiles.clear();
  }

  @action
  removeAllDevices() {
    this.devices.splice(0, this.devices.length);
  }

  @action
  async setPinConfig(profileId: number, pinId: number, config: Btj.PinConfig) {
    if (!this.conn) throw new Error("Not connected");
    // Update local cache
    this.profiles.get(profileId)!.pins.set(pinId, config);
    try {
      // Send to device
      await this.conn.invoke(new Btj.SetPinConfig(profileId, pinId, config));
    } catch (err: unknown) {
      this.logError(err, "profile");
      // Revert local cache change on error
      const profile = this.profiles.get(profileId);
      if (profile) {
        profile.pins.delete(pinId);
      }
    }
  }

  @action
  async setPotConfig(profileId: number, potId: number, config: Btj.PotConfig) {
    if (!this.conn) throw new Error("Not connected");
    // Update local cache
    this.profiles.get(profileId)!.pots.set(potId, config);
    try {
      // Send to device
      await this.conn.invoke(new Btj.SetPotConfig(profileId, potId, config));
    } catch (err: unknown) {
      this.logError(err, "profile");
      // Revert local cache change on error
      const profile = this.profiles.get(profileId);
      if (profile) {
        profile.pots.delete(potId);
      }
    }
  }

  @action
  async setIntgConfig(
    profileId: number,
    intgId: number,
    config: Btj.IntgConfig,
  ) {
    if (!this.conn) throw new Error("Not connected");
    // Update local cache
    this.profiles.get(profileId)!.intgs.set(intgId, config);
    try {
      // Send to device
      await this.conn.invoke(new Btj.SetIntgConfig(profileId, intgId, config));
    } catch (err: unknown) {
      this.logError(err, "profile");
      // Revert local cache change on error
      const profile = this.profiles.get(profileId);
      if (profile) {
        profile.intgs.delete(intgId);
      }
    }
  }

  @action
  async deleteDevice(addr: Btj.DevAddr): Promise<void> {
    if (!this.conn) throw new Error("Not connected");
    try {
      await this.conn.invoke(new Btj.DeleteDevice(addr));
    } catch (err: unknown) {
      this.logError(err, "device");
    }
  }

  @action
  async setDeviceProfile(addr: Btj.DevAddr, profile: number): Promise<void> {
    if (!this.conn) throw new Error("Not connected");
    try {
      await this.conn.invoke(new Btj.SetDevConfig(addr, { profile }));
    } catch (err: unknown) {
      this.logError(err, "device");
    }
  }

  @action
  async startScanning(): Promise<void> {
    if (!this.conn) {
      this.logError("Not connected", "connection");
      return;
    }
    try {
      await this.conn.invoke(new Btj.SetMode(Btj.SysMode.MANUAL, true));
      await this.conn.invoke(new Btj.StartScanning());
    } catch (err: unknown) {
      this.logError(err, "device");
    }
  }

  @action
  async stopScanning(): Promise<void> {
    if (!this.conn) return;
    try {
      await this.conn.invoke(new Btj.StopScanning());
    } catch (err: unknown) {
      this.logError(err, "device");
    }
  }

  @action
  async connectDevice(addr: Btj.DevAddr): Promise<void> {
    if (!this.conn) {
      this.logError("Not connected", "connection");
      return;
    }
    try {
      await this.stopScanning();
      await this.conn.invoke(new Btj.ConnectDevice(addr));
    } catch (err: unknown) {
      this.logError(err, "device");
    }
  }

  @action
  async setJoyPortMode(mode: Btj.JoyPortMode) {
    if (!this.conn) throw new Error("Not connected");
    try {
      if (mode === Btj.JoyPortMode.UART) {
        this.resetXep80TransportState();
      }
      await this.conn.invoke(new Btj.SetJoyPortMode(mode));
    } catch (err: unknown) {
      this.logError(err, "joyport");
    }
  }
}

// Singleton instance for global use
export const btj = new BtjModel();
